export const PACK_CHARGES: ChargeDef[] = RAW.map((r) =>
  chargeFromSvg(r.id, r.svg, {
    recolor: true,
    label: r.label,
    plural: r.plural,
    article: r.article === 'an' ? 'an' : 'a',
  }),
);

export const PACK_IDS: string[] = PACK_CHARGES.map((c) => c.id);
